if [ $? -ne 0 ]
then
   SHELL_RES=20
fi
# archivage et compression des fichiers generes
if [ -e $DATA_PUMP_DIR/$DUMP_FILE_NAME.dmp -o -e $DATA_PUMP_DIR/$DUMP_FILE_NAME.log ]
then
	echo "GOTO dump directory"
	cd $DATA_PUMP_DIR
	if [ $? -ne 0 ]
	then
	   SHELL_RES=20
	fi
	
	
fi


exit $SHELL_RES
